        cfg:GetLeaderTypeName()==d.leader and cfg:GetCivilizationTypeName()==d.civilization and
        Get(d.leader,'OWNER')==owner and Get(d.leader,'SOURCE')==source and
        Get(d.leader,'EVOLUTION_COST')==d.cost and
